fn reverse_digits(n: Int) -> Int {
    let mut result = 0
    let mut remaining = n
    while remaining > 0 {
        result = result * 10 + remaining % 10
        remaining = remaining / 10
    }
    result
}

fn main() {
    print(reverse_digits(1234))
}

